const API = require('../../utils/api');Page({data:{user:{},balance:0,totalSpent:0,visitCount:0},onShow(){const user=API.getCurrentUser();if(user){this.setData({user,balance:user.balance||0,totalSpent:user.totalSpent||0,visitCount:user.visitCount||0});API.getBalance().then(balance=>this.setData({balance}))}},goMyOrders(){wx.switchTab({url:'/pages/my-orders/my-orders'})},goMyCoupons(){wx.navigateTo({url:'/pages/my-coupons/my-coupons'})},goTopUp(){wx.showToast({title:'充值功能开发中',icon:'none'})},goRoomControl(){wx.navigateTo({url:'/pages/room-control/room-control'})}})